function ema(values:number[], period:number){ if(!values.length)return[]; const k=2/(period+1); const out=[values[0]]; for(let i=1;i<values.length;i++)out.push(values[i]*k+out[i-1]*(1-k)); return out; }
function targetDateLabel(value:string|undefined,lang:"en"|"es"){if(!value)return "—";const [y,m,d]=value.split("-").map(Number);return new Intl.DateTimeFormat(lang==="es"?"es-US":"en-US",{weekday:"long",year:"numeric",month:"long",day:"numeric",timeZone:"America/New_York"}).format(new Date(Date.UTC(y,m-1,d,12)))}
function etDateTime(value:number|string|null|undefined,lang:"en"|"es"){if(value==null)return "—";const date=new Date(value);if(!Number.isFinite(date.getTime()))return "—";return new Intl.DateTimeFormat(lang==="es"?"es-US":"en-US",{timeZone:"America/New_York",year:"numeric",month:"short",day:"numeric",hour:"numeric",minute:"2-digit",second:"2-digit",timeZoneName:"short"}).format(date)}
function ApiStamp({value,lang,label}:{value:number|string|null|undefined;lang:"en"|"es";label:string}){const date=value==null?null:new Date(value);return <time className="api-stamp" dateTime={date&&Number.isFinite(date.getTime())?date.toISOString():undefined}>{label} · {etDateTime(value,lang)}</time>}

