function median(values:number[]){const s=values.filter(Number.isFinite).sort((a,b)=>a-b);if(!s.length)return 0;const m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2}
function classifyCandle(c:Bar,prev:Bar|undefined,history:Bar[]){const range=Math.max(.0001,c.high-c.low),body=Math.abs(c.close-c.open),upper=c.high-Math.max(c.open,c.close),lower=Math.min(c.open,c.close)-c.low,ratio=body/range,bull=c.close>=c.open;const prior=history.length>=4?history.at(-1)!.close-history[0].close:0;const engulf=prev&&bull!==(prev.close>=prev.open)&&body>=Math.abs(prev.close-prev.open)*1.05&&Math.min(c.open,c.close)<=Math.min(prev.open,prev.close)&&Math.max(c.open,c.close)>=Math.max(prev.open,prev.close);if(engulf&&((bull&&prior<0)||(!bull&&prior>0)))return{type:bull?"Bullish engulfing":"Bearish engulfing",copy:"The body spans the prior opposite body after a short move. This is reversal-shaped evidence, not proof of a reversal."};if(ratio<=.08)return{type:"Long-legged doji",copy:"Open and close are nearly equal relative to the full range. Both sides pushed price, but neither held control into the current close."};if(ratio>=.1&&lower>=body*2.1&&upper<=body*.8&&prior<0)return{type:"Hammer-shaped rejection",copy:"Price traded lower after a short decline and recovered toward the body. Confirmation requires later price action."};if(ratio>=.1&&upper>=body*2.1&&lower<=body*.8&&prior>0)return{type:"Shooting-star rejection",copy:"Price traded higher after a short rise and returned toward the body. This shows rejection, not a guaranteed reversal."};if(ratio>=.88&&upper/range<=.06&&lower/range<=.06)return{type:bull?"Bullish marubozu":"Bearish marubozu",copy:"Most of the range is directional body with very small wicks. It describes strong control during this minute only."};if(ratio<.3)return{type:"Spinning top",copy:"A small body sits inside a wider range. The minute rotated in both directions and closed without clean control."};return{type:bull?"Bullish body candle":"Bearish body candle",copy:`This candle is ${bull?"above":"below"} its open. Its location, volume and follow-through matter more than the name.`}}
function candleRead(bars:Bar[]){if(!bars.length)return null;const c=bars.at(-1)!,prev=bars.at(-2),hist=bars.slice(-7,-2),pattern=classifyCandle(c,prev,hist);const range=Math.max(.01,c.high-c.low),body=Math.abs(c.close-c.open),bps=(c.close/c.open-1)*10000,bodyRatio=body/range,priorRanges=bars.slice(-21,-1).map(x=>(x.high-x.low)/x.open*10000),typical=Math.max(.1,median(priorRanges)),relative=Math.abs(bps)/typical,priorVolumes=bars.slice(-21,-1).map(x=>x.volume).filter(x=>x>0),avgVol=priorVolumes.reduce((a,b)=>a+b,0)/Math.max(1,priorVolumes.length),volumePace=avgVol?c.volume/avgVol:0;const recent5=bars.slice(-6,-1),recent15=bars.slice(-16,-1);const trend=(rows:Bar[])=>{if(rows.length<3)return"building";const change=rows.at(-1)!.close-rows[0].open,hh=rows.slice(1).filter((x,i)=>x.high>rows[i].high).length,hl=rows.slice(1).filter((x,i)=>x.low>rows[i].low).length,lh=rows.slice(1).filter((x,i)=>x.high<rows[i].high).length,ll=rows.slice(1).filter((x,i)=>x.low<rows[i].low).length;return change>0&&hh+hl>=lh+ll?"rising":change<0&&lh+ll>=hh+hl?"falling":"sideways"};const higherLow=prev?c.low>prev.low:false,lowerHigh=prev?c.high<prev.high:false;return{c,prev,pattern,bps,bodyRatio,relative,typical,volumePace,trend5:trend(recent5),trend15:trend(recent15),higherLow,lowerHigh,direction:bps>.75?"up":bps<-.75?"down":"flat",wick:upperLower(c),recent:bars.slice(-9)}}
function upperLower(c:Bar){const body=Math.abs(c.close-c.open),u=c.high-Math.max(c.open,c.close),l=Math.min(c.open,c.close)-c.low;return u>Math.max(body,l)*1.5?"upper rejection":l>Math.max(body,u)*1.5?"lower rejection":"balanced wicks"}

function SessionChart({bars,ema9,ema21,lang}:{bars:Bar[];ema9:number[];ema21:number[];lang:"en"|"es"}){
  const canvas=useRef<HTMLCanvasElement>(null);
  useEffect(()=>{const el=canvas.current;if(!el||bars.length<2)return;const visible=bars.slice(-120),offset=bars.length-visible.length,e9=ema9.slice(offset),e21=ema21.slice(offset),rect=el.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);el.width=rect.width*dpr;el.height=rect.height*dpr;const c=el.getContext("2d");if(!c)return;c.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,p={l:10,r:58,t:16,b:28};const vals=visible.flatMap(b=>[b.high,b.low]),min=Math.min(...vals),max=Math.max(...vals),span=Math.max(max-min,.01),plotW=w-p.l-p.r,step=plotW/visible.length,bodyW=Math.max(2,Math.min(8,step*.62));const x=(i:number)=>p.l+step*i+step/2,y=(v:number)=>p.t+(max-v)*(h-p.t-p.b)/span;c.clearRect(0,0,w,h);c.strokeStyle="rgba(118,151,176,.13)";c.lineWidth=1;for(let i=0;i<5;i++){const yy=p.t+i*(h-p.t-p.b)/4;c.beginPath();c.moveTo(p.l,yy);c.lineTo(w-p.r,yy);c.stroke();c.fillStyle="#8ea5b7";c.font="10px system-ui";c.fillText((max-i*span/4).toFixed(2),w-p.r+7,yy+3)}visible.forEach((b,i)=>{const color=b.close>=b.open?"#4ad69c":"#ff7777",xx=x(i);c.strokeStyle=color;c.lineWidth=1;c.beginPath();c.moveTo(xx,y(b.high));c.lineTo(xx,y(b.low));c.stroke();const top=y(Math.max(b.open,b.close)),bottom=y(Math.min(b.open,b.close));c.fillStyle=color;c.fillRect(xx-bodyW/2,top,bodyW,Math.max(1.5,bottom-top))});const line=(arr:number[],color:string,width:number)=>{c.beginPath();arr.forEach((v,i)=>i?c.lineTo(x(i),y(v)):c.moveTo(x(i),y(v)));c.strokeStyle=color;c.lineWidth=width;c.stroke()};line(e21,"#a98cff",1.5);line(e9,"#f5c75b",1.8);c.fillStyle="#8ea5b7";c.font="9px system-ui";[0,Math.floor((visible.length-1)/2),visible.length-1].forEach(i=>c.fillText(new Date(visible[i].time).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"}),Math.max(p.l,x(i)-18),h-8))},[bars,ema9,ema21]);
  return <canvas ref={canvas} aria-label={lang==="es"?"Gráfico de velas de un minuto de NVDA con EMA 9 y EMA 21":"NVDA one-minute candlestick chart with EMA 9 and EMA 21"}/>;
}

