 const localizedState=(value:string|null|undefined)=>{if(!value)return "—";if(!es)return value;const labels:Record<string,string>={"LONG":"LARGO","SHORT":"CORTO","WAIT":"ESPERAR","UP":"ALZA","DOWN":"BAJA","MIXED":"MIXTO","LOW":"BAJA","MODERATE":"MODERADA","HIGH":"ALTA","CRITICAL":"CRÍTICA","ELEVATED":"ELEVADA","CLEAR":"DESPEJADA","CLOSED":"CERRADO","PREMARKET":"PREAPERTURA","REGULAR":"SESIÓN REGULAR","AFTER HOURS":"POSESIÓN","OVERNIGHT":"NOCTURNA","BUYERS IN CONTROL":"COMPRADORES AL MANDO","SELLERS IN CONTROL":"VENDEDORES AL MANDO","MIXED / ROTATING":"MIXTO / ROTANDO","UPPER THIRD":"TERCIO SUPERIOR","MIDDLE THIRD":"TERCIO MEDIO","LOWER THIRD":"TERCIO INFERIOR","UNKNOWN":"DESCONOCIDA","READY":"LISTA","DEGRADED":"DEGRADADA","CALCULATING":"CALCULANDO","active":"activa","neutral":"neutral","unavailable":"no disponible","live":"activa","limited":"limitada","offline":"inactiva","rising":"ascendente","falling":"descendente","sideways":"lateral","building":"formándose","upper rejection":"rechazo superior","lower rejection":"rechazo inferior","balanced wicks":"mechas equilibradas","ABOVE":"ENCIMA","BELOW":"DEBAJO","NEAR":"CERCA","PRESENT":"PRESENTE","NOT PRESENT":"AUSENTE","Higher low":"Mínimo ascendente","Not a higher low":"Sin mínimo ascendente","Lower high":"Máximo descendente","Not a lower high":"Sin máximo descendente","compressed":"comprimido","separated":"separado"};return labels[value]??value};
